<?php
namespace App\Http\Controllers;
use App\Models\{Apprentice,TutorGroup,User};
use App\Support\{PortalActions,CentreManagerAccess as A,CentreOversight as O,CentreFollowups as F};
use Illuminate\Http\Request;
use Illuminate\Support\Str;
class CentreOversightController extends Controller {
 private function view(string $name,array $data=[]){return response()->view('centre-oversight.'.$name,$data)->header('Cache-Control','private, no-store')->header('Referrer-Policy','no-referrer');}
 private function period(Request $r):array {$d=$r->validate(['from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d']);$from=$d['from']??today()->subDays(70)->toDateString();$to=$d['to']??today()->toDateString();O::period($from,$to);return compact('from','to');}
 public function index(Request $r){$u=PortalActions::actor($r->user());$policy=A::policy($u);abort_unless($policy,403);$d=$r->validate(['group'=>'nullable|integer|min:1','search'=>'nullable|string|max:100','area'=>'nullable|in:training,attendance,reviews,functional_skills','page'=>'nullable|integer|min:1']);$area=$d['area']??array_values(array_diff($policy['areas'],['coordination']))[0];abort_unless(in_array($area,$policy['areas'],true),403);$period=$this->period($r);$q=A::people($u);if($d['group']??null){$q->where('tutor_group_id',(int)$d['group']);}if($search=trim($d['search']??'')){$pattern=PortalActionsController::pattern($search);$q->where(fn($q)=>$q->whereRaw('LOWER(reference) LIKE ? ESCAPE \'!\'',[$pattern])->orWhereRaw('LOWER(first_name) LIKE ? ESCAPE \'!\'',[$pattern])->orWhereRaw('LOWER(last_name) LIKE ? ESCAPE \'!\'',[$pattern]));}$people=$q->orderBy('last_name')->orderBy('first_name')->orderBy('id')->paginate(25)->withQueryString();$groups=TutorGroup::where('active',true)->when(!$policy['administrator'],fn($q)=>$q->whereIn('id',$policy['groups']))->orderBy('name')->get();return $this->view('index',compact('u','policy','people','groups','area','period'));}
 public function show(Request $r,Apprentice $apprentice,string $area){$u=PortalActions::actor($r->user());$period=$this->period($r);$position=O::position($u,$apprentice,$area,$period['from'],$period['to']);$owners=[];foreach($position['flags']as$key=>$flag){$owners[$key]=O::owners($apprentice,$area,$key);}$token=(string)Str::uuid();$canCoordinate=F::manager($u,$apprentice,$area);return $this->view('show',compact('u','apprentice','period','position','owners','token','canCoordinate'));}
 public function followup(Request $r,Apprentice $apprentice,string $area){$u=PortalActions::actor($r->user());$d=$r->validate(['flag'=>'required|string|max:48','from'=>'required|date_format:Y-m-d','to'=>'required|date_format:Y-m-d','source_hash'=>'required|regex:/^[a-f0-9]{64}$/D','owner_choice'=>['required','regex:/^[1-9][0-9]*:(tutor|mentor|maths_tutor|english_tutor)$/D'],'request_token'=>'required|uuid','due'=>'required|date_format:Y-m-d','reference'=>'required|string|min:5|max:1000','confirmed'=>'accepted']);[$ownerId,$ownerSlot]=explode(':',$d['owner_choice'],2);$w=F::create($u,(int)$r->session()->get('auth_version'),$apprentice,$area,$d['flag'],$d['from'],$d['to'],$d['source_hash'],User::findOrFail((int)$ownerId),$ownerSlot,$d['request_token'],$d['due'],$d['reference']);return to_route('centre-followups.show',$w)->with('status','Source-linked follow-up recorded for the current responsible staff member. No external message or source-record completion was created.');}
}
